import numpy as np, math
from sklearn.ensemble import HistGradientBoostingRegressor

HGB=dict(max_iter=250,learning_rate=0.08,max_leaf_nodes=31,l2_regularization=1)

def _hgb(X,y,seed):
    m=HistGradientBoostingRegressor(random_state=seed,**HGB)
    m.fit(X,y)
    return m

def _trend_slope(X,y,fn):
    ed=X[:,fn.index('elapsed_day')]
    cols=[np.ones(len(y)),ed]
    for name in ['hr','mnth','weathersit','weekday']:
        v=X[:,fn.index(name)]
        for k in np.unique(v)[1:]:
            cols.append((v==k).astype(float))
    for name in ['workingday','holiday','temp','hum','windspeed']:
        cols.append(X[:,fn.index(name)])
    A=np.column_stack(cols)
    coef=np.linalg.lstsq(A,np.log1p(y),rcond=None)[0]
    return float(coef[1])

def _branch(b,Xtr,ytr,Xte,fn,seed):
    info={}
    if b=='raw':
        p=_hgb(Xtr,ytr,seed).predict(Xte)
    elif b=='log':
        p=np.expm1(_hgb(Xtr,np.log1p(ytr),seed).predict(Xte))
    elif b=='log_trend':
        i=fn.index('elapsed_day'); iy=fn.index('yr')
        slope=_trend_slope(Xtr,ytr,fn)
        ref=float(Xtr[:,i].max())
        z=np.log1p(ytr)-slope*(Xtr[:,i]-ref)
        keep=[j for j in range(Xtr.shape[1]) if j not in (i,iy)]
        m=_hgb(Xtr[:,keep],z,seed)
        p=np.expm1(m.predict(Xte[:,keep])+slope*(Xte[:,i]-ref))
        info={'slope_per_day':slope,'annual_growth_factor':math.exp(365.0*slope),'ref_day':ref,'dropped_features':['elapsed_day','yr']}
    else:
        raise ValueError(b)
    return np.maximum(np.asarray(p,dtype=float),0.0),info

def fit_predict(train,inputs,seed):
    fn=list(train['feature_names'])
    X=np.asarray(train['X'],dtype=float); y=np.asarray(train['y'],dtype=float)
    Xte=np.asarray(inputs['X'],dtype=float)
    i=fn.index('elapsed_day')
    days=np.sort(np.unique(X[:,i]))
    branches=['raw','log','log_trend']
    scores={b:[] for b in branches}; errors={}; fold_info=[]
    for k in (1,2):
        lo=len(days)-61*k; hi=len(days)-61*(k-1)
        mte=np.isin(X[:,i],days[lo:hi]); mtr=X[:,i]<days[lo]
        fold_info.append({'fold':k,'train_days':int(len(np.unique(X[mtr,i]))),'holdout_day_range':[float(days[lo]),float(days[hi-1])],'holdout_rows':int(mte.sum())})
        for b in branches:
            try:
                p,_=_branch(b,X[mtr],y[mtr],X[mte],fn,seed)
                scores[b].append(float(np.sqrt(np.mean((p-y[mte])**2))))
            except Exception as exc:
                errors['%s_fold%d'%(b,k)]=type(exc).__name__
                scores[b].append(float('inf'))
    mean_scores={b:float(np.mean(scores[b])) for b in branches}
    selected=min(branches,key=lambda b:(mean_scores[b],branches.index(b)))
    fallback=None
    try:
        p,info=_branch(selected,X,y,Xte,fn,seed)
    except Exception as exc:
        fallback='raw_after_%s'%type(exc).__name__
        p,info=_branch('raw',X,y,Xte,fn,seed)
    nonfinite=int((~np.isfinite(p)).sum())
    if nonfinite:
        p=np.nan_to_num(p,nan=float(np.median(y)),posinf=float(y.max()),neginf=0.0)
    findings={'selected_branch':selected,'forward_fold_rmse':scores,'mean_forward_rmse':mean_scores,'folds':fold_info,'errors':errors,'fallback':fallback,'nonfinite_replaced':nonfinite,'final_info':info,'train_days_total':int(len(days)),'train_yr_share':float(np.mean(X[:,fn.index('yr')])),'note':'selection uses only training dates; no evaluation covariates used beyond prediction'}
    return {'prediction':p.tolist(),'findings':findings}

import numpy as np
import json
from sklearn.ensemble import HistGradientBoostingRegressor

BRANCHES = ['squared', 'poisson', 'log1p']


def _make(loss, seed):
    return HistGradientBoostingRegressor(max_iter=250, learning_rate=0.08, max_leaf_nodes=31,
                                         l2_regularization=1, loss=loss, random_state=seed)


def _fit_pred(branch, Xtr, ytr, Xte, seed):
    if branch == 'squared':
        m = _make('squared_error', seed)
        m.fit(Xtr, ytr)
        return m.predict(Xte)
    if branch == 'poisson':
        m = _make('poisson', seed)
        m.fit(Xtr, np.maximum(ytr, 0.0))
        return m.predict(Xte)
    if branch == 'log1p':
        m = _make('squared_error', seed)
        m.fit(Xtr, np.log1p(np.maximum(ytr, 0.0)))
        return np.expm1(m.predict(Xte))
    raise ValueError('unknown branch ' + str(branch))


def _rmse(p, y):
    return float(np.sqrt(np.mean((p - y) ** 2)))


def _date_mae(p, y, days):
    vals = []
    for d in np.unique(days):
        idx = days == d
        vals.append(float(np.mean(np.abs(p[idx] - y[idx]))))
    return float(np.mean(vals)) if vals else float('nan')


def fit_predict(train, inputs, seed):
    fn = list(train['feature_names'])
    X = np.asarray(train['X'], dtype=float)
    y = np.asarray(train['y'], dtype=float)
    Xe = np.asarray(inputs['X'], dtype=float)
    di = fn.index('elapsed_day')
    days = X[:, di]
    dmax = float(np.max(days))
    findings = {'branches': BRANCHES, 'folds': [], 'fold_rmse': {b: [] for b in BRANCHES},
                'fold_date_mae': {b: [] for b in BRANCHES}, 'errors': {}, 'fallback': None,
                'note': 'branch selection uses only training dates (two forward 61-day holdouts); evaluation covariates used only for final prediction; baseline HGB hyperparameters fixed'}
    for k in range(2):
        hi = dmax - 61.0 * k
        lo = hi - 61.0
        te = (days > lo) & (days <= hi)
        tr = days <= lo
        if te.sum() < 100 or tr.sum() < 500:
            findings['folds'].append({'fold': k + 1, 'skipped': True})
            continue
        findings['folds'].append({'fold': k + 1, 'holdout_day_range': [float(lo), float(hi)],
                                  'holdout_rows': int(te.sum()), 'train_rows': int(tr.sum())})
        for b in BRANCHES:
            try:
                p = _fit_pred(b, X[tr], y[tr], X[te], seed)
                p = np.where(np.isfinite(p), p, np.median(y[tr]))
                p = np.maximum(p, 0.0)
                findings['fold_rmse'][b].append(_rmse(p, y[te]))
                findings['fold_date_mae'][b].append(_date_mae(p, y[te], days[te]))
            except Exception as exc:
                findings['errors'][b + '_fold' + str(k + 1)] = type(exc).__name__
                findings['fold_rmse'][b].append(float('inf'))
                findings['fold_date_mae'][b].append(float('inf'))
    mean_rmse = {}
    mean_mae = {}
    for b in BRANCHES:
        r = findings['fold_rmse'][b]
        m = findings['fold_date_mae'][b]
        mean_rmse[b] = float(np.mean(r)) if r else float('inf')
        mean_mae[b] = float(np.mean(m)) if m else float('inf')
    order = sorted(BRANCHES, key=lambda b: (mean_rmse[b], BRANCHES.index(b)))
    selected = order[0] if np.isfinite(mean_rmse[order[0]]) else 'squared'
    findings['mean_forward_rmse'] = {b: (mean_rmse[b] if np.isfinite(mean_rmse[b]) else None) for b in BRANCHES}
    findings['mean_forward_date_mae'] = {b: (mean_mae[b] if np.isfinite(mean_mae[b]) else None) for b in BRANCHES}
    findings['selected_branch'] = selected
    findings['best_by_date_mae'] = min(BRANCHES, key=lambda b: (mean_mae[b], BRANCHES.index(b)))
    findings['train_rows'] = int(X.shape[0])
    findings['train_day_range'] = [float(np.min(days)), dmax]
    findings['eval_day_range'] = [float(np.min(Xe[:, di])), float(np.max(Xe[:, di]))]
    try:
        pred = _fit_pred(selected, X, y, Xe, seed)
    except Exception as exc:
        findings['errors']['final_' + selected] = type(exc).__name__
        findings['fallback'] = 'squared_error_after_final_fit_failure'
        pred = _fit_pred('squared', X, y, Xe, seed)
    pred = np.asarray(pred, dtype=float)
    bad = ~np.isfinite(pred)
    findings['nonfinite_replaced'] = int(bad.sum())
    if bad.any():
        pred[bad] = float(np.median(y))
    pred = np.maximum(pred, 0.0)
    findings['pred_summary'] = {'mean': float(np.mean(pred)), 'max': float(np.max(pred)), 'min': float(np.min(pred))}
    return {'prediction': pred.tolist(), 'findings': json.loads(json.dumps(findings))}

import numpy as np
import json
from sklearn.ensemble import HistGradientBoostingRegressor

BRANCHES = ['squared', 'deflate_drop', 'deflate_keep']
HGB = dict(max_iter=250, learning_rate=0.08, max_leaf_nodes=31, l2_regularization=1)
B_CLIP = 0.004


def _growth(days, y):
    ud, inv = np.unique(days, return_inverse=True)
    tot = np.bincount(inv, weights=y, minlength=len(ud))
    keep = tot > 0
    ud = ud[keep]
    tot = tot[keep]
    if len(ud) < 30:
        return 0.0, int(len(ud)), 'too_few_dates'
    w = 2.0 * np.pi * ud / 365.25
    A = np.column_stack([np.ones_like(ud), ud, np.sin(w), np.cos(w), np.sin(2 * w), np.cos(2 * w)])
    coef = np.linalg.lstsq(A, np.log(tot), rcond=None)[0]
    b_raw = float(coef[1])
    b = float(np.clip(b_raw, -B_CLIP, B_CLIP))
    return b, int(len(ud)), ('clipped' if b != b_raw else 'ok')


def _fit_pred(branch, Xtr, ytr, Xte, di, yi, seed, info):
    if branch == 'squared':
        m = HistGradientBoostingRegressor(loss='squared_error', random_state=seed, **HGB)
        m.fit(Xtr, ytr)
        return m.predict(Xte)
    b, nd, status = _growth(Xtr[:, di], ytr)
    ref = float(np.max(Xtr[:, di]))
    gtr = np.exp(b * (Xtr[:, di] - ref))
    gte = np.exp(b * (Xte[:, di] - ref))
    info[branch] = {'growth_b_per_day': b, 'annual_factor': float(np.exp(365.0 * b)), 'n_dates': nd,
                    'status': status, 'eval_factor_range': [float(np.min(gte)), float(np.max(gte))]}
    if branch == 'deflate_drop':
        keep = [j for j in range(Xtr.shape[1]) if j not in (di, yi)]
        Xtr2, Xte2 = Xtr[:, keep], Xte[:, keep]
    elif branch == 'deflate_keep':
        Xtr2, Xte2 = Xtr, Xte
    else:
        raise ValueError('unknown branch ' + str(branch))
    m = HistGradientBoostingRegressor(loss='squared_error', random_state=seed, **HGB)
    m.fit(Xtr2, ytr / gtr)
    return m.predict(Xte2) * gte


def _rmse(p, y):
    return float(np.sqrt(np.mean((p - y) ** 2)))


def _date_mae(p, y, days):
    vals = []
    for d in np.unique(days):
        idx = days == d
        vals.append(float(np.mean(np.abs(p[idx] - y[idx]))))
    return float(np.mean(vals)) if vals else float('nan')


def fit_predict(train, inputs, seed):
    fn = list(train['feature_names'])
    X = np.asarray(train['X'], dtype=float)
    y = np.asarray(train['y'], dtype=float)
    Xe = np.asarray(inputs['X'], dtype=float)
    di = fn.index('elapsed_day')
    yi = fn.index('yr')
    days = X[:, di]
    dmax = float(np.max(days))
    findings = {'branches': BRANCHES, 'folds': [], 'fold_rmse': {b: [] for b in BRANCHES},
                'fold_date_mae': {b: [] for b in BRANCHES}, 'fold_growth': [], 'errors': {}, 'fallback': None,
                'note': 'growth rate b fitted on log daily totals of training dates only (trend + 2 harmonics); target deflated by exp(b*(day-last_train_day)) and predictions re-inflated; branch selection by mean RMSE over two forward 61-day training holdouts; HGB hyperparameters fixed at baseline; evaluation covariates used only for final prediction'}
    for k in range(2):
        hi = dmax - 61.0 * k
        lo = hi - 61.0
        te = (days > lo) & (days <= hi)
        tr = days <= lo
        if te.sum() < 100 or tr.sum() < 500:
            findings['folds'].append({'fold': k + 1, 'skipped': True})
            continue
        findings['folds'].append({'fold': k + 1, 'holdout_day_range': [float(lo), float(hi)],
                                  'holdout_rows': int(te.sum()), 'train_rows': int(tr.sum())})
        info = {}
        for b in BRANCHES:
            try:
                p = _fit_pred(b, X[tr], y[tr], X[te], di, yi, seed, info)
                p = np.where(np.isfinite(p), p, np.median(y[tr]))
                p = np.maximum(p, 0.0)
                findings['fold_rmse'][b].append(_rmse(p, y[te]))
                findings['fold_date_mae'][b].append(_date_mae(p, y[te], days[te]))
            except Exception as exc:
                findings['errors'][b + '_fold' + str(k + 1)] = type(exc).__name__
                findings['fold_rmse'][b].append(float('inf'))
                findings['fold_date_mae'][b].append(float('inf'))
        findings['fold_growth'].append(info)
    mean_rmse = {}
    mean_mae = {}
    for b in BRANCHES:
        r = findings['fold_rmse'][b]
        m = findings['fold_date_mae'][b]
        mean_rmse[b] = float(np.mean(r)) if r else float('inf')
        mean_mae[b] = float(np.mean(m)) if m else float('inf')
    order = sorted(BRANCHES, key=lambda b: (mean_rmse[b], BRANCHES.index(b)))
    selected = order[0] if np.isfinite(mean_rmse[order[0]]) else 'squared'
    findings['mean_forward_rmse'] = {b: (mean_rmse[b] if np.isfinite(mean_rmse[b]) else None) for b in BRANCHES}
    findings['mean_forward_date_mae'] = {b: (mean_mae[b] if np.isfinite(mean_mae[b]) else None) for b in BRANCHES}
    findings['selected_branch'] = selected
    findings['best_by_date_mae'] = min(BRANCHES, key=lambda b: (mean_mae[b], BRANCHES.index(b)))
    findings['train_rows'] = int(X.shape[0])
    findings['train_day_range'] = [float(np.min(days)), dmax]
    findings['eval_day_range'] = [float(np.min(Xe[:, di])), float(np.max(Xe[:, di]))]
    final_info = {}
    try:
        pred = _fit_pred(selected, X, y, Xe, di, yi, seed, final_info)
    except Exception as exc:
        findings['errors']['final_' + selected] = type(exc).__name__
        findings['fallback'] = 'squared_error_after_final_fit_failure'
        final_info = {}
        pred = _fit_pred('squared', X, y, Xe, di, yi, seed, final_info)
    findings['final_growth'] = final_info
    pred = np.asarray(pred, dtype=float)
    bad = ~np.isfinite(pred)
    findings['nonfinite_replaced'] = int(bad.sum())
    if bad.any():
        pred[bad] = float(np.median(y))
    pred = np.maximum(pred, 0.0)
    findings['pred_summary'] = {'mean': float(np.mean(pred)), 'max': float(np.max(pred)), 'min': float(np.min(pred))}
    return {'prediction': pred.tolist(), 'findings': json.loads(json.dumps(findings))}

import numpy as np
import json
from collections import defaultdict
from sklearn.ensemble import HistGradientBoostingRegressor

BRANCHES = ['base', 'lag_point', 'lag_smooth']
LAG = 364


def _make(seed):
    return HistGradientBoostingRegressor(max_iter=250, learning_rate=0.08, max_leaf_nodes=31,
                                         l2_regularization=1, loss='squared_error', random_state=seed)


def _tables(days, hrs, y):
    hour_tab = {}
    day_tot = defaultdict(float)
    for d, h, v in zip(days, hrs, y):
        hour_tab[(int(round(d)), int(round(h)))] = float(v)
        day_tot[int(round(d))] += float(v)
    return hour_tab, dict(day_tot)


def _lag_feats(days, hrs, hour_tab, day_tot, smooth):
    n = len(days)
    f_hr = np.full(n, np.nan)
    f_day = np.full(n, np.nan)
    for i in range(n):
        d = int(round(days[i])) - LAG
        h = int(round(hrs[i]))
        if smooth:
            hv = [hour_tab[(dd, h)] for dd in (d - 7, d, d + 7) if (dd, h) in hour_tab]
            dv = [day_tot[dd] for dd in range(d - 3, d + 4) if dd in day_tot]
            if len(hv) >= 2:
                f_hr[i] = float(np.mean(hv))
            if len(dv) >= 4:
                f_day[i] = float(np.mean(dv))
        else:
            if (d, h) in hour_tab:
                f_hr[i] = hour_tab[(d, h)]
            if d in day_tot:
                f_day[i] = day_tot[d]
    return np.column_stack([f_hr, f_day])


def _features(branch, Xtr, ytr, Xte, di, hi):
    if branch == 'base':
        return Xtr, Xte, None
    smooth = branch == 'lag_smooth'
    hour_tab, day_tot = _tables(Xtr[:, di], Xtr[:, hi], ytr)
    ftr = _lag_feats(Xtr[:, di], Xtr[:, hi], hour_tab, day_tot, smooth)
    fte = _lag_feats(Xte[:, di], Xte[:, hi], hour_tab, day_tot, smooth)
    info = {'train_lag_hr_available_frac': float(np.mean(np.isfinite(ftr[:, 0]))),
            'eval_lag_hr_available_frac': float(np.mean(np.isfinite(fte[:, 0]))),
            'eval_lag_day_available_frac': float(np.mean(np.isfinite(fte[:, 1])))}
    return np.hstack([Xtr, ftr]), np.hstack([Xte, fte]), info


def _fit_pred(branch, Xtr, ytr, Xte, seed, di, hi):
    A, B, info = _features(branch, Xtr, ytr, Xte, di, hi)
    m = _make(seed)
    m.fit(A, ytr)
    return m.predict(B), info


def _rmse(p, y):
    return float(np.sqrt(np.mean((p - y) ** 2)))


def _date_mae(p, y, days):
    vals = []
    for d in np.unique(days):
        idx = days == d
        vals.append(float(np.mean(np.abs(p[idx] - y[idx]))))
    return float(np.mean(vals)) if vals else float('nan')


def _yoy_diag(days, mnth, yrs, y):
    hour_tab, day_tot = _tables(days, np.zeros_like(days), y)
    out = {}
    cur = defaultdict(float)
    prev = defaultdict(float)
    seen = set()
    for d, mo, yv in zip(days, mnth, yrs):
        dd = int(round(d))
        if yv < 0.5 or dd in seen:
            continue
        seen.add(dd)
        if dd in day_tot and (dd - LAG) in day_tot:
            cur[int(round(mo))] += day_tot[dd]
            prev[int(round(mo))] += day_tot[dd - LAG]
    for mo in sorted(cur):
        if prev[mo] > 0:
            out['month_' + str(mo)] = float(cur[mo] / prev[mo])
    tc = sum(cur.values())
    tp = sum(prev.values())
    out['overall'] = float(tc / tp) if tp > 0 else None
    return out


def fit_predict(train, inputs, seed):
    fn = list(train['feature_names'])
    X = np.asarray(train['X'], dtype=float)
    y = np.asarray(train['y'], dtype=float)
    Xe = np.asarray(inputs['X'], dtype=float)
    di = fn.index('elapsed_day')
    hi = fn.index('hr')
    mi = fn.index('mnth')
    yi = fn.index('yr')
    days = X[:, di]
    dmax = float(np.max(days))
    findings = {'branches': BRANCHES, 'lag_days': LAG, 'folds': [],
                'fold_rmse': {b: [] for b in BRANCHES}, 'fold_date_mae': {b: [] for b in BRANCHES},
                'fold_lag_info': {b: [] for b in BRANCHES if b != 'base'}, 'errors': {}, 'fallback': None,
                'note': 'lag features are training-label counts at elapsed_day-364 same hr (point) or mean of lag 357/364/371 same hr plus mean daily total over lag week (smooth); NaN when unavailable; tables built only from the fold/final training labels; branch selection by mean RMSE over two forward 61-day training holdouts; fold 2 training rows have no lag so its lag branches cannot learn lag relations; HGB hyperparameters fixed at baseline; evaluation covariates used only for final prediction'}
    try:
        findings['train_yoy_daily_total_ratio_2012_vs_2011'] = _yoy_diag(days, X[:, mi], X[:, yi], y)
    except Exception as exc:
        findings['errors']['yoy_diag'] = type(exc).__name__
    for k in range(2):
        hi_d = dmax - 61.0 * k
        lo_d = hi_d - 61.0
        te = (days > lo_d) & (days <= hi_d)
        tr = days <= lo_d
        if te.sum() < 100 or tr.sum() < 500:
            findings['folds'].append({'fold': k + 1, 'skipped': True})
            continue
        findings['folds'].append({'fold': k + 1, 'holdout_day_range': [float(lo_d), float(hi_d)],
                                  'holdout_rows': int(te.sum()), 'train_rows': int(tr.sum())})
        for b in BRANCHES:
            try:
                p, info = _fit_pred(b, X[tr], y[tr], X[te], seed, di, hi)
                p = np.where(np.isfinite(p), p, np.median(y[tr]))
                p = np.maximum(p, 0.0)
                findings['fold_rmse'][b].append(_rmse(p, y[te]))
                findings['fold_date_mae'][b].append(_date_mae(p, y[te], days[te]))
                if info is not None:
                    findings['fold_lag_info'][b].append(info)
            except Exception as exc:
                findings['errors'][b + '_fold' + str(k + 1)] = type(exc).__name__
                findings['fold_rmse'][b].append(float('inf'))
                findings['fold_date_mae'][b].append(float('inf'))
    mean_rmse = {}
    mean_mae = {}
    for b in BRANCHES:
        r = findings['fold_rmse'][b]
        m = findings['fold_date_mae'][b]
        mean_rmse[b] = float(np.mean(r)) if r else float('inf')
        mean_mae[b] = float(np.mean(m)) if m else float('inf')
    order = sorted(BRANCHES, key=lambda b: (mean_rmse[b], BRANCHES.index(b)))
    selected = order[0] if np.isfinite(mean_rmse[order[0]]) else 'base'
    findings['mean_forward_rmse'] = {b: (mean_rmse[b] if np.isfinite(mean_rmse[b]) else None) for b in BRANCHES}
    findings['mean_forward_date_mae'] = {b: (mean_mae[b] if np.isfinite(mean_mae[b]) else None) for b in BRANCHES}
